  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest */
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {

  /* NOTE ON OPTIMIZATIONS
   *
   * 1. Coefficient computation is hoisted and common exponentials are
   *    reused, avoiding redundant EXP/POW evaluations.
   *
   * 2. The three horizontal passes (forward recursion, backward recursion,
   *    combination) are fused per row. Rows are independent, so this
   *    reordering does not change the result while improving cache locality.
   *
   * 3. The vertical passes are restructured to traverse the image in
   *    row-major order (i outer, j inner). We maintain, for each column,
   *    the necessary recursive state in small 1D buffers. This preserves
   *    the original per-column IIR recurrences but turns the vertical
   *    passes into contiguous memory accesses along the inner loop.
   *
   * 4. The final vertical combination imgOut = c2 * (y1 + y2) is fused
   *    into the vertical backward pass: as soon as y2(i,j) is known, we
   *    immediately form imgOut(i,j). This is safe because no later
   *    computation depends on y2 other than this pointwise sum.
   */

  int i, j;

  /* Use PolyBench's loop bounds. */
  const int w_bound = _PB_W;
  const int h_bound = _PB_H;

  /* Filter coefficients.  Algebra is identical to the original code,
   * but we reuse common exponentials instead of recomputing them. */
  DATA_TYPE k;
  DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
  DATA_TYPE b1, b2, c1, c2;

#pragma scop

  {
    const DATA_TYPE one  = SCALAR_VAL(1.0);
    const DATA_TYPE two  = SCALAR_VAL(2.0);

    /* Common exponentials/powers. */
    const DATA_TYPE exp_neg_alpha   = EXP_FUN(-alpha);
    const DATA_TYPE exp_neg_2alpha  = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
    const DATA_TYPE exp_pos_2alpha  = EXP_FUN(SCALAR_VAL( 2.0) * alpha);
    const DATA_TYPE pow_2_neg_alpha = POW_FUN(SCALAR_VAL(2.0), -alpha);

    k  = (one - exp_neg_alpha) * (one - exp_neg_alpha) /
         (one + two * alpha * exp_neg_alpha - exp_pos_2alpha);

    a1 = k;
    a2 = k * exp_neg_alpha * (alpha - one);
    a3 = k * exp_neg_alpha * (alpha + one);
    a4 = -k * exp_neg_2alpha;

    a5 = a1;
    a6 = a2;
    a7 = a3;
    a8 = a4;

    b1 = pow_2_neg_alpha;
    b2 = -exp_neg_2alpha;

    c1 = one;
    c2 = one;
  }

  /* --------------------------------------------------------------------
   *  Horizontal pass: per-row forward + backward recursions and combine
   * --------------------------------------------------------------------
   *
   * For each row i:
   *   - forward (causal) recursion along j into y1[i][*]
   *   - backward (anti-causal) recursion along j into y2[i][*]
   *   - pointwise combination into imgOut[i][*]
   *
   * This is equivalent to the original three separate loops over i,
   * because rows are independent and the recurrences are purely along j.
   */
  for (i = 0; i < w_bound; i++) {
    DATA_TYPE xm1 = SCALAR_VAL(0.0);
    DATA_TYPE ym1 = SCALAR_VAL(0.0);
    DATA_TYPE ym2 = SCALAR_VAL(0.0);

    DATA_TYPE xp1 = SCALAR_VAL(0.0);
    DATA_TYPE xp2 = SCALAR_VAL(0.0);
    DATA_TYPE yp1 = SCALAR_VAL(0.0);
    DATA_TYPE yp2 = SCALAR_VAL(0.0);

    /* Row pointers for better locality and to help the compiler. */
    DATA_TYPE *imgIn_row  = imgIn[i];
    DATA_TYPE *y1_row     = y1[i];
    DATA_TYPE *y2_row     = y2[i];
    DATA_TYPE *imgOut_row = imgOut[i];

    /* Horizontal forward recursion (left-to-right). */
    for (j = 0; j < h_bound; j++) {
      DATA_TYPE x = imgIn_row[j];
      DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

      y1_row[j] = y;
      xm1 = x;
      ym2 = ym1;
      ym1 = y;
    }

    /* Horizontal backward recursion (right-to-left). */
    xp1 = SCALAR_VAL(0.0);
    xp2 = SCALAR_VAL(0.0);
    yp1 = SCALAR_VAL(0.0);
    yp2 = SCALAR_VAL(0.0);

    for (j = h_bound - 1; j >= 0; j--) {
      DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

      y2_row[j] = y;
      xp2 = xp1;
      xp1 = imgIn_row[j];
      yp2 = yp1;
      yp1 = y;
    }

    /* Horizontal combination: imgOut = c1 * (y1 + y2). */
    for (j = 0; j < h_bound; j++) {
      imgOut_row[j] = c1 * (y1_row[j] + y2_row[j]);
    }
  }

  /* --------------------------------------------------------------------
   *  Vertical pass: forward + backward recursions using column state
   * --------------------------------------------------------------------
   *
   * Original code:
   *   - processes each column j separately (outer loop over j),
   *     recursing along i (inner loop) with stride-H accesses.
   *
   * Here we keep the same mathematical recurrences but traverse in
   * row-major order and keep, for each column j, the needed recursion
   * state in small 1D buffers v_*[j].  This improves cache locality for
   * imgOut, y1, and y2, while preserving exact dependencies.
   */

  /* --- Vertical forward (top-to-bottom) pass: produces y1 from imgOut --- */

  DATA_TYPE v_tm1[h_bound];
  DATA_TYPE v_ym1[h_bound];
  DATA_TYPE v_ym2[h_bound];

  /* Zero-border initial conditions for all columns. */
  for (j = 0; j < h_bound; j++) {
    v_tm1[j] = SCALAR_VAL(0.0);
    v_ym1[j] = SCALAR_VAL(0.0);
    v_ym2[j] = SCALAR_VAL(0.0);
  }

  /* For each row i, update all columns' forward recurrences. */
  for (i = 0; i < w_bound; i++) {
    DATA_TYPE *imgOut_row = imgOut[i];
    DATA_TYPE *y1_row     = y1[i];

    for (j = 0; j < h_bound; j++) {
      DATA_TYPE prev_x  = v_tm1[j];
      DATA_TYPE prev_y1 = v_ym1[j];
      DATA_TYPE prev_y2 = v_ym2[j];
      DATA_TYPE x       = imgOut_row[j];

      DATA_TYPE y = a5 * x + a6 * prev_x + b1 * prev_y1 + b2 * prev_y2;
      y1_row[j] = y;

      v_tm1[j] = x;
      v_ym2[j] = prev_y1;
      v_ym1[j] = y;
    }
  }

  /* --- Vertical backward (bottom-to-top) pass fused with final combine --- */

  DATA_TYPE v_tp1[h_bound];
  DATA_TYPE v_tp2[h_bound];
  DATA_TYPE v_yp1[h_bound];
  DATA_TYPE v_yp2[h_bound];

  /* Zero-border initial conditions for all columns. */
  for (j = 0; j < h_bound; j++) {
    v_tp1[j] = SCALAR_VAL(0.0);
    v_tp2[j] = SCALAR_VAL(0.0);
    v_yp1[j] = SCALAR_VAL(0.0);
    v_yp2[j] = SCALAR_VAL(0.0);
  }

  /* Process rows from bottom to top. For each (i,j):
   *   - compute vertical anti-causal response y2[i][j],
   *   - update per-column state v_*[j],
   *   - immediately form the final output imgOut[i][j] = c2*(y1 + y2).
   *
   * This is equivalent to the original separate vertical-backward and
   * final-combination loops, since each imgOut[i][j] depends only on
   * y1[i][j] and y2[i][j], and y2 participates only in this sum.
   */
  for (i = w_bound - 1; i >= 0; i--) {
    DATA_TYPE *imgOut_row = imgOut[i];
    DATA_TYPE *y1_row     = y1[i];
    DATA_TYPE *y2_row     = y2[i];

    for (j = 0; j < h_bound; j++) {
      DATA_TYPE tp1 = v_tp1[j];
      DATA_TYPE tp2 = v_tp2[j];
      DATA_TYPE yp1 = v_yp1[j];
      DATA_TYPE yp2 = v_yp2[j];

      DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
      y2_row[j] = y;  /* keep y2 explicitly, as in the original code */

      DATA_TYPE x = imgOut_row[j];

      v_tp2[j] = tp1;
      v_tp1[j] = x;
      v_yp2[j] = yp1;
      v_yp1[j] = y;

      imgOut_row[j] = c2 * (y1_row[j] + y);
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

