/* Original code provided by Gael Deest */
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn,  W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1,     W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2,     W, H, w, h)) {
    int i, j;
    DATA_TYPE xm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

    /* Create restrict-qualified row pointers to help the optimizer.
       POLYBENCH_2D(...) parameters are VLAs; here we create explicit
       pointer aliases with the second dimension 'h'. */
    DATA_TYPE (* __restrict imgIn_)[h]  = imgIn;
    DATA_TYPE (* __restrict imgOut_)[h] = imgOut;
    DATA_TYPE (* __restrict y1_)[h]     = y1;
    DATA_TYPE (* __restrict y2_)[h]     = y2;

    /* For the optimized vertical passes we maintain, for each column j,
       the recursive state in small 1D arrays. This allows us to traverse
       imgOut, y1, y2 in row-major order (i outer, j inner), which gives
       contiguous memory accesses along j instead of the original strided
       column accesses. Dependencies are only along i for each fixed j, so
       this reordering is semantically exact. */
    const int H_ = _PB_H;
    DATA_TYPE v_tm1[H_];  /* previous imgOut value in column j (forward) */
    DATA_TYPE v_ym1[H_];  /* previous y1 value in column j (forward)     */
    DATA_TYPE v_ym2[H_];  /* y1 two steps back in column j (forward)     */

    DATA_TYPE v_tp1[H_];  /* next imgOut value in column j (backward)    */
    DATA_TYPE v_tp2[H_];  /* two steps ahead imgOut in column j          */
    DATA_TYPE v_yp1[H_];  /* next y2 value in column j (backward)        */
    DATA_TYPE v_yp2[H_];  /* y2 two steps ahead in column j (backward)   */

#pragma scop
    /* --- Coefficient computation ---
       Hoist and share exponentials to avoid redundant transcendental calls. */
    const DATA_TYPE one  = SCALAR_VAL(1.0);
    const DATA_TYPE two  = SCALAR_VAL(2.0);
    const DATA_TYPE emA  = EXP_FUN(-alpha);                  /* e^{-alpha}   */
    const DATA_TYPE em2A = EXP_FUN(SCALAR_VAL(-2.0) * alpha);/* e^{-2alpha}  */
    const DATA_TYPE e2A  = EXP_FUN(two * alpha);             /* e^{ 2alpha}  */

    k = (one - emA) * (one - emA) /
        (one + two * alpha * emA - e2A);

    const DATA_TYPE ke = k * emA;

    a1 = a5 = k;
    a2 = a6 = ke * (alpha - one);
    a3 = a7 = ke * (alpha + one);
    a4 = a8 = -k * em2A;

    b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
    b2 = -em2A;

    c1 = c2 = one;

    /* ------------------------------------------------------------------ */
    /* 1) Horizontal passes (per row):                                   */
    /*    - causal (left-to-right) into y1                               */
    /*    - anti-causal (right-to-left) into y2                          */
    /*    - combination y1 + y2 into imgOut                              */
    /*                                                                    */
    /* Rows are independent, so we safely fuse the three horizontal       */
    /* loops by row i to improve locality of imgIn/y1/y2/imgOut.         */
    /* ------------------------------------------------------------------ */
    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE * __restrict imgIn_row  = imgIn_[i];
        DATA_TYPE * __restrict y1_row     = y1_[i];
        DATA_TYPE * __restrict y2_row     = y2_[i];
        DATA_TYPE * __restrict imgOut_row = imgOut_[i];

        /* Forward recursion along the row: j = 0 .. H-1 */
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        xm1 = SCALAR_VAL(0.0);
        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE x = imgIn_row[j];
            const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_row[j] = y;
            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Backward recursion along the row: j = H-1 .. 0 */
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        for (j = _PB_H - 1; j >= 0; j--) {
            const DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_row[j] = y;
            const DATA_TYPE x = imgIn_row[j];
            xp2 = xp1;
            xp1 = x;
            yp2 = yp1;
            yp1 = y;
        }

        /* Horizontal combination: imgOut = c1 * (y1 + y2) */
        for (j = 0; j < _PB_H; j++) {
            imgOut_row[j] = c1 * (y1_row[j] + y2_row[j]);
        }
    }

    /* ------------------------------------------------------------------ */
    /* 2) Vertical passes on imgOut:                                      */
    /*    We restructure the original column-wise vertical recurrences    */
    /*    into row-major order using per-column state arrays v_*[j].      */
    /*                                                                    */
    /*    For each column j, the exact same recurrence along i (row) is   */
    /*    preserved; operations for different columns are simply          */
    /*    interleaved, which is legal because columns are independent.    */
    /*    This improves cache locality and enables vectorization along j. */
    /* ------------------------------------------------------------------ */

    /* 2a) Vertical causal recursion (top-to-bottom) producing new y1.    */
    for (j = 0; j < _PB_H; j++) {
        v_tm1[j] = SCALAR_VAL(0.0);
        v_ym1[j] = SCALAR_VAL(0.0);
        v_ym2[j] = SCALAR_VAL(0.0);
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE * __restrict imgOut_row = imgOut_[i];
        DATA_TYPE * __restrict y1_row     = y1_[i];
        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE tm1_j = v_tm1[j];
            const DATA_TYPE ym1_j = v_ym1[j];
            const DATA_TYPE ym2_j = v_ym2[j];
            const DATA_TYPE x     = imgOut_row[j];

            const DATA_TYPE y = a5 * x + a6 * tm1_j + b1 * ym1_j + b2 * ym2_j;
            y1_row[j] = y;

            v_tm1[j] = x;
            v_ym2[j] = ym1_j;
            v_ym1[j] = y;
        }
    }

    /* 2b) Vertical anti-causal recursion (bottom-to-top) fused with       */
    /*     final vertical combination: imgOut = c2 * (y1 + y2).            */
    for (j = 0; j < _PB_H; j++) {
        v_tp1[j] = SCALAR_VAL(0.0);
        v_tp2[j] = SCALAR_VAL(0.0);
        v_yp1[j] = SCALAR_VAL(0.0);
        v_yp2[j] = SCALAR_VAL(0.0);
    }

    for (i = _PB_W - 1; i >= 0; i--) {
        DATA_TYPE * __restrict imgOut_row = imgOut_[i];
        DATA_TYPE * __restrict y1_row     = y1_[i];
        DATA_TYPE * __restrict y2_row     = y2_[i];

        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE tp1_j = v_tp1[j];
            const DATA_TYPE tp2_j = v_tp2[j];
            const DATA_TYPE yp1_j = v_yp1[j];
            const DATA_TYPE yp2_j = v_yp2[j];

            /* Backward vertical recurrence for this (i,j). */
            const DATA_TYPE y = a7 * tp1_j + a8 * tp2_j + b1 * yp1_j + b2 * yp2_j;
            y2_row[j] = y;

            const DATA_TYPE x = imgOut_row[j];

            v_tp2[j] = tp1_j;
            v_tp1[j] = x;
            v_yp2[j] = yp1_j;
            v_yp1[j] = y;

            /* Final combination: overwrite imgOut with fully filtered value. */
            imgOut_row[j] = c2 * (y1_row[j] + y);
        }
    }

#pragma endscop
}


