#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "deriche.h"


/* Array initialization. */
static
void init_array (int w, int h, DATA_TYPE* alpha,
		 DATA_TYPE POLYBENCH_2D(imgIn,W,H,w,h),
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))
{
  int i, j;

  *alpha=0.25; //parameter of the filter

  //input should be between 0 and 1 (grayscale image pixel)
  for (i = 0; i < w; i++)
     for (j = 0; j < h; j++)
	imgIn[i][j] = (DATA_TYPE) ((313*i+991*j)%65536) / 65535.0f;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int w, int h,
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest */
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i, j;

    /* Horizontal-pass state (per row). */
    DATA_TYPE xm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE yp1, yp2;

    /* Vertical-pass state (per column), restructured for row-major access.
       These are small 1D buffers (O(H)) that keep the last few values for
       each column, allowing us to traverse imgOut, y1, y2 in row-major order
       during the vertical passes instead of strided column-major access. */
    DATA_TYPE v_tm1[h];
    DATA_TYPE v_ym1[h];
    DATA_TYPE v_ym2[h];
    DATA_TYPE v_tp1[h];
    DATA_TYPE v_tp2[h];
    DATA_TYPE v_yp1[h];
    DATA_TYPE v_yp2[h];

    /* Filter coefficients. */
    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* Compute and hoist all loop-invariant coefficients.  We explicitly
       precompute the exponentials once to avoid redundant calls inside
       the large image loops. */
    const DATA_TYPE exp_neg_alpha  = EXP_FUN(-alpha);
    const DATA_TYPE exp_neg_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
    const DATA_TYPE exp_pos_2alpha = EXP_FUN(SCALAR_VAL( 2.0) * alpha);

    k  = (SCALAR_VAL(1.0) - exp_neg_alpha) * (SCALAR_VAL(1.0) - exp_neg_alpha) /
         (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_neg_alpha - exp_pos_2alpha);

    a1 = a5 = k;

    const DATA_TYPE k_exp_neg = k * exp_neg_alpha;
    a2 = a6 = k_exp_neg * (alpha - SCALAR_VAL(1.0));
    a3 = a7 = k_exp_neg * (alpha + SCALAR_VAL(1.0));

    a4 = a8 = -k * exp_neg_2alpha;

    b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
    b2 = -exp_neg_2alpha;

    c1 = c2 = SCALAR_VAL(1.0);

    /* ---------------- Horizontal pass (left-right and right-left) -------- */

    /* Forward (causal) recursion along each row: uses row-major order already. */
    for (i = 0; i < _PB_W; i++) {
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        xm1 = SCALAR_VAL(0.0);
        for (j = 0; j < _PB_H; j++) {
            y1[i][j] = a1 * imgIn[i][j] + a2 * xm1 + b1 * ym1 + b2 * ym2;
            xm1 = imgIn[i][j];
            ym2 = ym1;
            ym1 = y1[i][j];
        }
    }

    /* Backward (anti-causal) recursion along each row. */
    for (i = 0; i < _PB_W; i++) {
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        for (j = _PB_H - 1; j >= 0; j--) {
            y2[i][j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            xp2 = xp1;
            xp1 = imgIn[i][j];
            yp2 = yp1;
            yp1 = y2[i][j];
        }
    }

    /* Horizontal combination: pointwise, fully parallelizable. */
    for (i = 0; i < _PB_W; i++)
        for (j = 0; j < _PB_H; j++) {
            imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
        }

    /* ---------------- Vertical pass (top-bottom and bottom-top) ---------- */
    /* Original code scans each column separately with strided memory
       accesses (i varying, j fixed).  Here we keep exactly the same
       recurrences but traverse the image in row-major order, using
       per-column state arrays v_*[j] to carry the 1D IIR state along i.
       This improves cache locality for imgOut, y1 and y2.               */

    /* Forward vertical recursion: initialize per-column state. */
    for (j = 0; j < _PB_H; j++) {
        v_tm1[j] = SCALAR_VAL(0.0);
        v_ym1[j] = SCALAR_VAL(0.0);
        v_ym2[j] = SCALAR_VAL(0.0);
    }

    /* Forward (causal) vertical pass: i increases, but we access all columns
       in each row so that accesses to imgOut[i][j] and y1[i][j] are contiguous
       in memory along j. */
    for (i = 0; i < _PB_W; i++) {
        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE prev_tm1 = v_tm1[j];
            const DATA_TYPE prev_ym1 = v_ym1[j];
            const DATA_TYPE prev_ym2 = v_ym2[j];
            const DATA_TYPE curr     = imgOut[i][j];

            const DATA_TYPE res = a5 * curr +
                                  a6 * prev_tm1 +
                                  b1 * prev_ym1 +
                                  b2 * prev_ym2;
            y1[i][j] = res;

            v_tm1[j] = curr;
            v_ym2[j] = prev_ym1;
            v_ym1[j] = res;
        }
    }

    /* Backward vertical recursion: initialize per-column state. */
    for (j = 0; j < _PB_H; j++) {
        v_tp1[j] = SCALAR_VAL(0.0);
        v_tp2[j] = SCALAR_VAL(0.0);
        v_yp1[j] = SCALAR_VAL(0.0);
        v_yp2[j] = SCALAR_VAL(0.0);
    }

    /* Backward (anti-causal) vertical pass: i decreases.  For each row i we
       process all columns, again in row-major order, while maintaining a
       separate IIR state per column in the v_* arrays.  For a fixed j, the
       sequence of operations over i is identical to the original code. */
    for (i = _PB_W - 1; i >= 0; i--) {
        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE prev_tp1 = v_tp1[j];
            const DATA_TYPE prev_tp2 = v_tp2[j];
            const DATA_TYPE prev_yp1 = v_yp1[j];
            const DATA_TYPE prev_yp2 = v_yp2[j];

            const DATA_TYPE res = a7 * prev_tp1 +
                                  a8 * prev_tp2 +
                                  b1 * prev_yp1 +
                                  b2 * prev_yp2;
            y2[i][j] = res;

            const DATA_TYPE curr = imgOut[i][j];

            v_tp2[j] = prev_tp1;
            v_tp1[j] = curr;
            v_yp2[j] = prev_yp1;
            v_yp1[j] = res;
        }
    }

    /* Final vertical combination: overwrite imgOut with fully filtered image. */
    for (i = 0; i < _PB_W; i++)
        for (j = 0; j < _PB_H; j++)
            imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut), POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
